class Solution {
  public long minMergeCost(int[][] lists) {
    int n = lists.length, full = (1 << n) - 1;
    int[][] merged = new int[full + 1][];
    merged[0] = new int[0];
    long[] dp = new long[full + 1];
    int[] med = new int[full + 1];
    for (int mask = 1; mask <= full; mask++) {
      int low = Integer.numberOfTrailingZeros(mask);
      int[] a = merged[mask & (mask - 1)], b = lists[low];
      int[] res = new int[a.length + b.length];
      int i = 0, j = 0, p = 0;
      while (i < a.length && j < b.length) res[p++] = a[i] <= b[j] ? a[i++] : b[j++];
      while (i < a.length) res[p++] = a[i++];
      while (j < b.length) res[p++] = b[j++];
      merged[mask] = res;
      med[mask] = res[(res.length - 1) / 2];
    }
    long INF = Long.MAX_VALUE / 4;
    for (int mask = 1; mask <= full; mask++) {
      if ((mask & (mask - 1)) == 0) {
        dp[mask] = 0;
        continue;
      }
      dp[mask] = INF;
      int lowBit = mask & -mask, rest = mask ^ lowBit;
      for (int sub = rest; ; sub = (sub - 1) & rest) {
        int a = sub | lowBit, b = mask ^ a;
        if (b != 0) {
          long cost = dp[a] + dp[b] + merged[mask].length + Math.abs((long) med[a] - med[b]);
          if (cost < dp[mask]) dp[mask] = cost;
        }
        if (sub == 0) break;
      }
    }
    return dp[full];
  }
}
